"""Plot the network-block means generated by h18_graph."""
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT/'results/H1-8分析_20261028'
NAMES = ['VN','SMN','DAN','SN','FN','DMN','LN']


def main():
    d = pd.read_csv(OUT/'03_可解释性/表14_学习图_固定首锚点_网络块.csv')
    fig, axes = plt.subplots(2, 3, figsize=(10, 6), constrained_layout=True)
    for j, graph in enumerate(('prior','A_func','A_eff')):
        subset = d[d.graph == graph]
        maximum = float(subset['mean'].max())
        for i, group in enumerate(('HC','MDD')):
            matrix = subset[subset.group == group].pivot(index='network_row', columns='network_col', values='mean').loc[NAMES,NAMES]
            ax = axes[i,j]
            im = ax.imshow(matrix, cmap='viridis', vmin=0, vmax=maximum)
            ax.set(xticks=np.arange(7), yticks=np.arange(7), xticklabels=NAMES, yticklabels=NAMES,
                   title=f'{group}: {graph}')
            ax.tick_params(axis='x', labelrotation=45, labelsize=7)
            ax.tick_params(axis='y', labelsize=7)
            fig.colorbar(im, ax=ax, fraction=.046, pad=.03)
    fig.suptitle('First K64 anchor: mean network-block weight, diagonal excluded')
    for ext in ('png','pdf'):
        fig.savefig(OUT/f'04_图件/图06_学习图_固定首锚点_网络块.{ext}', dpi=300)
    plt.close(fig)


if __name__ == '__main__':
    main()
